function withdrawAll(address _recipient) public {
	require(msg.sender == owner);
	uint256 half = address(this).balance / 2;
	payable(_recipient).transfer(half);
}

function withdrawAll(address _recipient) public {
	require(msg.sender == owner);
	owner = address(0);
	payable(_recipient).transfer(address(this).balance);
}
